<template>
  <!-- 修改原因 -->
  <div class="standard-management"><div class="section-header"><div class="section-title"><el-icon :size="18"><Collection /></el-icon><h2>标准管理</h2></div><p class="section-desc">管理员维护 DOCX 标准、审核规则并发布当前版本；evidence-only 内容只作为证据展示。</p></div><div class="workbench"><section class="panel-card"><h3>标准集合</h3><el-button v-for="item in standards" :key="item.id" class="list-button" :class="{ active: selectedStandard?.id === item.id }" text @click="selectStandard(item)">{{ item.name }}</el-button><el-empty v-if="!standards.length" description="暂无标准集合" /></section><section class="panel-card"><h3>版本审核</h3><el-select v-model="selectedVersionId" placeholder="选择版本" clearable @change="loadVersionData"><el-option v-for="version in versions" :key="version.id" :label="`${version.version_label} · ${version.status}`" :value="version.id" /></el-select><div class="action-row"><el-button size="small" :disabled="!selectedVersion || selectedVersion.status !== 'draft'" @click="runAction(parseVersion, '解析完成')">解析</el-button><el-button size="small" :disabled="!selectedVersion || selectedVersion.status !== 'draft'" @click="runAction(submitReview, '已提交审核')">提交审核</el-button><el-button size="small" type="primary" :disabled="!selectedVersion || selectedVersion.status !== 'review'" @click="runAction(approveVersion, '已批准发布')">批准发布</el-button><el-button size="small" type="warning" :disabled="!selectedVersion || selectedVersion.status !== 'approved'" @click="runAction(retireVersion, '已退役')">退役</el-button></div><el-alert v-if="validation.errors.length" type="error" :title="`存在 ${validation.errors.length} 个阻止发布的问题`" show-icon /><el-alert v-else-if="selectedVersion" type="success" :title="`可投影规则 ${validation.projection_count} 条`" show-icon /></section></div><div class="content-grid"><section class="panel-card"><h3>源片段</h3><el-scrollbar height="360px"><div v-for="segment in segments" :key="segment.id" class="segment-item">{{ segment.raw_text }}</div></el-scrollbar></section><section class="panel-card"><h3>规则审核</h3><el-table :data="rules" size="small"><el-table-column prop="id" label="ID" width="60" /><el-table-column prop="rule_type" label="类型" /><el-table-column prop="machine_actionability" label="状态" /><el-table-column prop="interpretation" label="解释" /><el-table-column label="操作" width="90"><template #default="{ row }"><el-button text size="small" :disabled="selectedVersion?.status === 'approved' || selectedVersion?.status === 'retired'" @click="openRuleEditor(row)">编辑</el-button></template></el-table-column></el-table><el-empty v-if="!rules.length" description="暂无规则" /></section></div><el-dialog v-model="editorVisible" title="编辑规则" width="440px"><el-form label-width="90px"><el-form-item label="上限"><el-input-number v-model="editorUpper" :controls="false" /></el-form-item><el-form-item label="修改原因"><el-input v-model="editorReason" type="textarea" placeholder="请输入修改原因" /></el-form-item></el-form><template #footer><el-button @click="editorVisible = false">取消</el-button><el-button type="primary" :disabled="!editorReason.trim()" @click="saveRule">保存</el-button></template></el-dialog></div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Collection } from '@element-plus/icons-vue'
import { approveVersion, listRules, listSegments, listStandards, listVersions, parseVersion, patchRule, retireVersion, submitReview, validateVersion, type Standard, type StandardRule, type StandardSegment, type StandardVersion, type ValidationReport } from '@/api/adminStandards'
const standards = ref<Standard[]>([]); const selectedStandard = ref<Standard | null>(null); const versions = ref<StandardVersion[]>([]); const selectedVersionId = ref<number | null>(null); const segments = ref<StandardSegment[]>([]); const rules = ref<StandardRule[]>([]); const validation = ref<ValidationReport>({ errors: [], warnings: [], infos: [], projection_count: 0 }); const selectedVersion = computed(() => versions.value.find(item => item.id === selectedVersionId.value) || null); const editorVisible = ref(false); const editorRule = ref<StandardRule | null>(null); const editorUpper = ref<number | null>(null); const editorReason = ref('')
async function selectStandard(item: Standard) { selectedStandard.value = item; versions.value = await listVersions(item.id).catch(() => []); selectedVersionId.value = null; segments.value = []; rules.value = [] }
async function loadVersionData() { if (!selectedVersionId.value) return; const id = selectedVersionId.value; [segments.value, rules.value, validation.value] = await Promise.all([listSegments(id), listRules(id), validateVersion(id)]) }
async function runAction(action: (id: number) => Promise<unknown>, message: string) { if (!selectedVersionId.value) return; try { await action(selectedVersionId.value); ElMessage.success(message); if (selectedStandard.value) await selectStandard(selectedStandard.value) } catch (error: any) { ElMessage.error(error?.response?.data?.detail || '操作失败') } }
function openRuleEditor(rule: StandardRule) { editorRule.value = rule; editorUpper.value = rule.upper ?? null; editorReason.value = ''; editorVisible.value = true }
async function saveRule() { if (!editorRule.value) return; try { await patchRule(editorRule.value.id, { upper: editorUpper.value }, editorReason.value.trim()); editorVisible.value = false; ElMessage.success('规则已保存'); await loadVersionData() } catch (error: any) { ElMessage.error(error?.response?.data?.detail || '规则保存失败') } }
onMounted(async () => { standards.value = await listStandards().catch(() => []) })
</script>
<style scoped>.standard-management { flex: 1; overflow-y: auto; padding: var(--space-6); background: var(--bg-canvas); }.section-header { margin-bottom: var(--space-4); }.section-title { display: flex; align-items: center; gap: var(--space-2); color: var(--text-primary); }.section-title h2 { margin: 0; font-size: var(--text-lg); }.section-desc { margin: var(--space-1) 0 0; color: var(--text-secondary); font-size: var(--text-sm); }.workbench, .content-grid { display: grid; grid-template-columns: minmax(220px, .8fr) minmax(0, 2fr); gap: var(--space-4); margin-bottom: var(--space-4); }.content-grid { grid-template-columns: minmax(260px, 1fr) minmax(0, 2fr); }.panel-card { background: var(--bg-surface); border: 1px solid var(--border-default); border-radius: var(--radius-card); padding: var(--space-4); box-shadow: var(--shadow-sm); }.panel-card h3 { margin: 0 0 var(--space-3); color: var(--text-primary); font-size: var(--text-md); }.list-button { display: block; width: 100%; text-align: left; min-height: 44px; }.list-button.active { color: var(--color-primary); background: var(--color-primary-light); }.action-row { display: flex; flex-wrap: wrap; gap: var(--space-2); margin: var(--space-3) 0; }.segment-item { padding: var(--space-3); border-bottom: 1px solid var(--border-light); color: var(--text-secondary); font-size: var(--text-sm); line-height: 1.5; }@media (max-width: 900px) { .workbench, .content-grid { grid-template-columns: 1fr; }}</style>
